#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
double mu[2]={0.06,0.04},cov[2][2]={{0.04,0.005},{0.005,0.01}},lambda=2,best=-1e100,bestW=0;
for(int k=0;k<=1000;k++){double w=k/1000.0,mean=w*mu[0]+(1-w)*mu[1];
double variance=w*w*cov[0][0]+(1-w)*(1-w)*cov[1][1]+2*w*(1-w)*cov[0][1];
double score=mean-lambda*variance/2;
if(score>best){best=score;bestW=w;}}
cout<<bestW<<" "<<best<<"\n";
return 0;
}

